import fs from 'fs';
import * as esbuild from 'esbuild';

/* 1. Inline the ground maps. Textures loaded over file:// are blocked by CORS,
      so the only way this opens by double-click is as data URIs. */
const uri = f => 'data:image/webp;base64,' +
  fs.readFileSync(`../assets/textures/${f}`).toString('base64');
fs.writeFileSync('../src/textures.gen.js',
  '/* generated by tools/build-3d.mjs - do not edit */\nexport const GROUND = ' +
  JSON.stringify({
    color: uri('ground-stone_color_512.webp'),
    normal: uri('ground-stone_normalgl_512.webp'),
    rough: uri('ground-stone_roughness_512.webp'),
  }, null, 0) + ';\n');

/* Audio inlined as data URIs - same file:// CORS rule as the textures.
   To use externally sourced files instead, point these three at them. */
const AUDIO = {
  drone: 'ambient-drone.mp3',
  gate: 'gate-close.mp3',
  bell: 'bell-oldage.mp3',
};
const au = f => 'data:audio/mpeg;base64,' + fs.readFileSync('../assets/audio/' + f).toString('base64');
fs.writeFileSync('../src/audio.gen.js',
  '/* generated by tools/build-3d.mjs - do not edit */\nexport const AUDIO = ' +
  JSON.stringify({ drone: au(AUDIO.drone), gate: au(AUDIO.gate), bell: au(AUDIO.bell) }, null, 0) + ';\n');

/* MIT requires the notice be retained in redistributed builds */
const BANNER = '/*! Bundled: three.js (c) 2010-2025 three.js authors, MIT License; ' +
  'howler.js (c) 2013-2024 James Simpson / GoldFire Studios, MIT License. ' +
  'Scene code, audio and assets: CC0 / original. See assets/LICENSES.md */';

/* 2. Bundle into one IIFE. ES module imports are also blocked over file://,
      so nothing may remain as a separate request. */
async function bundle(entry) {
  const out = await esbuild.build({
    entryPoints: [entry],
    bundle: true, minify: true, format: 'iife', target: 'es2020',
    write: false, legalComments: 'eof',
    /* the entry lives in ../src but three is installed here */
    nodePaths: ['node_modules'],
  });
  return out.outputFiles[0].text;
}

const BASE = `
:root{--bg:#0a0908;--ink:#cdc3b2;--dim:#6b6459;--faint:#332f2a}
*{box-sizing:border-box}
html,body{margin:0;height:100%;background:var(--bg);color:var(--ink);overflow:hidden}
body{font:16px/1.75 Georgia,"Iowan Old Style","Palatino Linotype",Palatino,serif;
 -webkit-font-smoothing:antialiased;-webkit-text-size-adjust:100%}
#view{position:fixed;inset:0;z-index:0}
#view canvas{display:block;width:100%;height:100%}
.err{position:absolute;inset:0;display:grid;place-items:center;padding:2rem;text-align:center;color:var(--dim)}
`;

/* ---------- the dev harness ---------- */
const studyShell = js => `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="color-scheme" content="dark"><title>Before the Law — scene study</title>
<style>${BASE}
#ctl{position:fixed;left:50%;bottom:calc(1.6rem + env(safe-area-inset-bottom,0px));
 transform:translateX(-50%);display:flex;gap:.5rem;z-index:3}
#ctl button{background:rgba(10,9,8,.72);border:1px solid var(--faint);color:var(--dim);
 font:.66rem/1 ui-sans-serif,system-ui,sans-serif;letter-spacing:.17em;text-transform:uppercase;
 padding:.75rem 1.1rem;cursor:pointer;border-radius:2px;transition:color 400ms ease,border-color 400ms ease}
#ctl button:hover{color:var(--ink)}#ctl button.on{color:var(--ink);border-color:var(--dim)}
#cap{position:fixed;top:1.15rem;left:50%;transform:translateX(-50%);z-index:3;font-style:italic;
 font-size:.94rem;color:var(--dim);text-align:center;text-shadow:0 0 12px var(--bg);pointer-events:none;padding:0 1rem}
</style></head><body>
<div id="view"></div><p id="cap">Before the law stands a doorkeeper.</p>
<nav id="ctl"><button type="button" data-s="1" class="on">Arrival</button>
<button type="button" data-s="2">The long wait</button>
<button type="button" data-s="3">Old age</button></nav>
<script>${BANNER}${js}</script></body></html>`;

/* ---------- the game ---------- */
const gameShell = js => `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="color-scheme" content="dark"><title>Before the Law</title>
<style>${BASE}
/* the radiance is bright enough to kill dim prose, so the lower band gets a scrim */
#scrim{position:fixed;left:0;right:0;bottom:0;height:62%;z-index:1;pointer-events:none;
 background:linear-gradient(to top,rgba(10,9,8,.90) 0%,rgba(10,9,8,.80) 36%,rgba(10,9,8,.44) 62%,rgba(10,9,8,0) 100%);
 transition:height 2600ms ease}
body.s3 #scrim{height:72%;
 background:linear-gradient(to top,rgba(10,9,8,.97) 0%,rgba(10,9,8,.93) 34%,rgba(10,9,8,.70) 60%,rgba(10,9,8,0) 100%)}

#ui{position:fixed;inset:0;z-index:2;display:grid;grid-template-rows:auto 1fr auto;
 max-width:36rem;margin:0 auto;padding:0 1.5rem;pointer-events:none}

#tableau{padding-top:clamp(1.5rem,4vh,2.6rem);text-align:center;font-style:italic;
 color:var(--dim);font-size:.94rem;opacity:0;text-shadow:0 0 14px var(--bg),0 0 6px var(--bg);
 transition:opacity 1800ms ease}
#tableau.in{opacity:1}
body.s3 #tableau.in{opacity:.45}

#lower{display:flex;flex-direction:column;justify-content:flex-end;
 padding-bottom:calc(clamp(1.6rem,4.5vh,3rem) + env(safe-area-inset-bottom,0px))}

#text{transition:opacity 1500ms ease,font-size 2600ms ease;padding-bottom:1.6rem}
#text.out{opacity:0}
body.s3 #text{font-size:.92em;color:#a49f97;padding:1.5rem .9rem 1.7rem;margin:0 -.9rem;
 background:linear-gradient(to top,rgba(10,9,8,.88) 0%,rgba(10,9,8,.84) 62%,rgba(10,9,8,.55) 86%,rgba(10,9,8,0) 100%)}
.line{margin:0 0 1.15em;opacity:0;transition:opacity 1200ms ease;text-wrap:pretty;
 text-shadow:0 0 16px var(--bg),0 0 7px var(--bg),0 1px 2px var(--bg)}
.line.in{opacity:1}
.line:last-child{margin-bottom:0}

/* bottom-anchored so ENTER never moves between scenes */
#choices{display:flex;flex-direction:column;justify-content:flex-end;min-height:12.5rem;
 opacity:0;transition:opacity 900ms ease;pointer-events:auto}
#choices.in{opacity:1}
#choices:not(.in) button{pointer-events:none}
#choices button{display:block;width:100%;margin:0;padding:.85rem .1rem;text-align:left;
 background:none;border:0;border-top:1px solid var(--faint);color:var(--dim);
 font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
 font-size:.76rem;letter-spacing:.16em;text-transform:uppercase;line-height:1.4;cursor:pointer;
 user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent;
 transition:color 500ms ease,text-shadow 900ms ease}
#choices button:last-child{border-bottom:1px solid var(--faint)}
#choices button:hover,#choices button:focus-visible{color:var(--ink)}
#choices button:focus-visible{outline:1px solid var(--dim);outline-offset:4px}

/* in old age the ENTER button is the brightest thing on the screen */
body.s3 #choices button{color:var(--faint)}
body.s3 #choices button:hover,body.s3 #choices button:focus-visible{color:var(--dim)}
body.s3 #choices button.enter{color:#ffd79a;text-shadow:0 0 22px rgba(255,196,107,.5),0 0 8px rgba(255,196,107,.35)}
body.s3 #choices button.enter:hover,body.s3 #choices button.enter:focus-visible{color:#fff0d6}

#years{position:fixed;top:1.1rem;right:1.2rem;z-index:3;
 font:.68rem/1 ui-sans-serif,system-ui,sans-serif;letter-spacing:.14em;text-transform:uppercase;
 color:#5a534a;text-shadow:0 0 10px var(--bg);transition:opacity 1600ms ease;pointer-events:none}
#years.gone{opacity:0}

#black{position:fixed;inset:0;z-index:4;background:#000;opacity:0;pointer-events:none;
 transition:opacity 1800ms ease;display:grid;place-items:center;padding:2rem}
#black.on{opacity:1;pointer-events:auto}
#final{max-width:34rem;margin:0;text-align:center;color:#9c9384;opacity:0;
 transition:opacity 2600ms ease;text-wrap:pretty}
#final.in{opacity:1}
#final b{font-weight:normal;color:#cfc6b6}

#again{position:fixed;bottom:1.25rem;right:1.35rem;z-index:5;width:auto;border:0;background:none;
 font:.66rem/1 ui-sans-serif,system-ui,sans-serif;letter-spacing:.16em;text-transform:uppercase;
 color:#2e2c29;padding:.5rem;cursor:pointer;opacity:0;pointer-events:none;
 transition:opacity 2000ms ease,color 500ms ease}
#again.in{opacity:1;pointer-events:auto}
#again:hover,#again:focus-visible{color:#6b6459}

@media (max-width:760px){
  #ui{padding:0 1.15rem}
  #scrim{height:70%}
  #text{font-size:.98rem;padding-bottom:1.2rem}
  /* 48px minimum touch target */
  #choices button{font-size:.72rem;letter-spacing:.13em;padding:1rem .1rem;min-height:48px}
  #choices{min-height:13.5rem}
  #tableau{font-size:.86rem}
}
@media (max-height:560px){
  #choices{min-height:10.5rem}
  #choices button{padding:.7rem .1rem;min-height:44px}
  #text{font-size:.92rem}
}
</style></head><body class="s1">
<div id="view"></div>
<div id="scrim"></div>
<div id="ui">
  <header id="tableau">Before the law stands a doorkeeper.</header>
  <div></div>
  <div id="lower"><main id="text"></main><nav id="choices" aria-label="Choices"></nav></div>
</div>
<div id="years" aria-hidden="true">0 years</div>
<div id="black"><p id="final"></p></div>
<button id="again" type="button">Begin again</button>
<script>${BANNER}${js}</script></body></html>`;

const targets = [
  ['../src/study.js', '../scene-3d.html', studyShell],
  ['../src/game.js', '../before-the-law-3d.html', gameShell],
];
for (const [entry, out, shell] of targets) {
  const js = await bundle(entry);
  const html = shell(js);
  fs.writeFileSync(out, html);
  console.log(out.replace('../', '').padEnd(24),
    (html.length / 1048576).toFixed(2) + ' MB   (js+textures ' + (js.length / 1024).toFixed(0) + ' KB)');
}
